CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', photo_path text, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own profile read" ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY "Own profile create" ON public.profiles FOR INSERT TO authenticated WITH CHECK (id = auth.uid());
CREATE POLICY "Own profile update" ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE TABLE public.studio_uploads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, name text NOT NULL, path text NOT NULL UNIQUE, mime_type text NOT NULL, size_bytes bigint NOT NULL, engine text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, DELETE ON public.studio_uploads TO authenticated;
GRANT ALL ON public.studio_uploads TO service_role;
ALTER TABLE public.studio_uploads ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own uploads read" ON public.studio_uploads FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE POLICY "Own uploads create" ON public.studio_uploads FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid() AND split_part(path, '/', 1) = auth.uid()::text);
CREATE POLICY "Own uploads delete" ON public.studio_uploads FOR DELETE TO authenticated USING (user_id = auth.uid());
CREATE POLICY "Private studio objects read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'nixora-uploads' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Private studio objects insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'nixora-uploads' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Private studio objects delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'nixora-uploads' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE TABLE public.studio_subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, provider text NOT NULL, provider_subscription_id text UNIQUE, plan_code text NOT NULL, status text NOT NULL DEFAULT 'pending', price_kobo bigint NOT NULL, credits_per_period integer NOT NULL, seat_limit integer NOT NULL DEFAULT 1, period_start timestamptz, period_end timestamptz, cancel_at_period_end boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.studio_subscriptions TO authenticated;
GRANT ALL ON public.studio_subscriptions TO service_role;
ALTER TABLE public.studio_subscriptions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own subscription read" ON public.studio_subscriptions FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.studio_group_seats (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subscription_id uuid NOT NULL REFERENCES public.studio_subscriptions(id), user_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (subscription_id, user_id));
GRANT SELECT ON public.studio_group_seats TO authenticated;
GRANT ALL ON public.studio_group_seats TO service_role;
ALTER TABLE public.studio_group_seats ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own seat read" ON public.studio_group_seats FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE OR REPLACE FUNCTION public.enforce_studio_seat_limit() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ DECLARE cap integer; BEGIN SELECT seat_limit INTO cap FROM public.studio_subscriptions WHERE id = NEW.subscription_id AND status = 'active' FOR UPDATE; IF cap IS NULL THEN RAISE EXCEPTION 'Active subscription required'; END IF; IF (SELECT count(*) FROM public.studio_group_seats WHERE subscription_id = NEW.subscription_id) >= cap THEN RAISE EXCEPTION 'Seat limit reached'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER studio_seat_limit BEFORE INSERT ON public.studio_group_seats FOR EACH ROW EXECUTE FUNCTION public.enforce_studio_seat_limit();
ALTER TABLE public.payments ADD COLUMN product_code text, ADD COLUMN pricing_version text, ADD COLUMN credit_value_snapshot jsonb, ADD COLUMN value_protected_until timestamptz, ADD COLUMN subscription_id uuid REFERENCES public.studio_subscriptions(id);
CREATE OR REPLACE FUNCTION public.public_waitlist_total() RETURNS bigint LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT count(*) FROM public.waitlist_signups; $$;
REVOKE ALL ON FUNCTION public.public_waitlist_total() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.public_waitlist_total() TO anon, authenticated, service_role;